import{z as p,x as E,o as s,c as A,q as i,j as l,D as e,d as r,s as o,S as d,b as t}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse('{"title":"多路选择器","description":"","frontmatter":{"title":"多路选择器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mux-select.md","filePath":"cs/mux-select.md","lastUpdated":1791413859000}'),B={name:"cs/mux-select.md"};function m(c,a,u,D,h,_){const n=E("Mermaid");return s(),A("div",null,[a[2]||(a[2]=i('<h1 id="多路选择器" tabindex="-1">多路选择器 <a class="header-anchor" href="#多路选择器" aria-label="Permalink to &quot;多路选择器&quot;">​</a></h1><div class="epigraph"><p>选择线指出哪一路数据应当出现在输出；数据通路上的「如果」多数先做成这个块。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/critical-path">关键路径</a>给门网贴了 \\(t_{pd}\\)。本课不重算关键路径公式，也不从布尔最小项再展开一张总表。缺口是：后课 ALU、寄存器堆读口、单周期数据通路，反复出现「在 \\(2^k\\) 路数据里挑 1 路」。需要一个有名字的组合块：<strong>多路选择器</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最小项可以写「\\(s=00\\) 则出 \\(d_0\\)，\\(\\ldots\\)」，但每次从卡诺图做起太慢。缺口是固定模块：数据输入 \\(d_0,\\ldots,d_{2^k-1}\\)，选择 \\(s\\) 为 \\(k\\) 位，输出 \\(y=d_s\\)。功能是一个 \\(k\\) 位译码再与数据相与后或起来——与<a href="/cs/decoder-encoder">译码器</a>共享结构，本课先钉 MUX。</p><p><span class="marginnote">直觉类比：MUX 像铁路道岔——几条轨道只放一路车通行，选择线就是扳道员；不需要时间表，信号一到立刻换道，也不会记住上一次扳向哪边。</span></p><p>CMOS 可用传输管或门级实现。延迟随 \\(k\\) 增加：树形 MUX 深度 \\(O(k)\\)。本课用单位延迟直觉，不画晶体管。</p><h3 id="mux-不是时序「选通脉冲」" tabindex="-1">MUX 不是时序「选通脉冲」 <a class="header-anchor" href="#mux-不是时序「选通脉冲」" aria-label="Permalink to &quot;MUX 不是时序「选通脉冲」&quot;">​</a></h3><p>选择线与数据一样是电平。没有时钟，输出跟着输入组合变。把 MUX 当成采样保持，会与后课锁存混名。使能端只是多一个「强制某常数」的数据输入或输出与门。</p><p><span class="marginnote">Harris 把 2:1、4:1 当积木。Patterson/Hennessy 的单周期图里 ALUSrc、MemtoReg 都是 MUX。本课不把那些控制信号提前译码。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>\\(2^k\\):1 MUX 的布尔式 \\(y=\\sum_i m_i(s)\\cdot d_i\\)，其中 \\(m_i\\) 是 \\(s\\) 的最小项。宽数据则按位复制同一套选择。级联：两个 2:1 拼 4:1，延迟相加。</p><p><span class="marginnote">数字实例：8 路（\\(2^3\\):1）选择需要 3 位选择线；用 7 个 2:1 搭成三层树，若每层 1 个门延迟，选择到输出约 3 个单位——宽扇入的一层实现门少，但每扇门又大又慢，树形因此更常被画进关键路径。</span></p>',13)),(s(),l(d,null,{default:e(()=>[o(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%A4%9A%E8%B7%AF%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20MUX%5B%22%E9%80%89%E6%8B%A9%E7%BA%BF%E9%80%89%E9%80%9A%22%5D%0A%20%20MUX%20--%3E%20Y%5B%22%E4%B8%80%E8%B7%AF%E8%BE%93%E5%87%BA%22%5D%0A%20%20Y%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%AF%91%E7%A0%81%E4%B8%8E%E7%BC%96%E7%A0%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"数据通路把「指令选立即数还是寄存器」做成 MUX，控制端来自后课控制器。延迟计入关键路径：MemtoReg 往往在访存之后，成为单周期周期的一部分。本课只提供块；谁驱动 \\(s\\)，要等控制真值表。",-1)),a[5]||(a[5]=t("p",null,"MUX 也可以实现任意组合函数：把数据端接常量 0/1，选择端接变量，即真值表——这是延迟与面积通常很差的实现，LUT 的前身直觉，本课不展开 FPGA。",-1)),(s(),l(d,null,{default:e(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20S0%5B%22%E4%BD%8E%E4%BD%8D%E9%80%89%E6%8B%A9%20s0%22%5D%20--%3E%20A%7B%222%3A1%20A%22%7D%0A%20%20S0%20--%3E%20B%7B%222%3A1%20B%22%7D%0A%20%20D0%5B%22d0%22%5D%20--%3E%20A%0A%20%20D1%5B%22d1%22%5D%20--%3E%20A%0A%20%20D2%5B%22d2%22%5D%20--%3E%20B%0A%20%20D3%5B%22d3%22%5D%20--%3E%20B%0A%20%20A%20--%3E%20C%7B%222%3A1%20C%22%7D%0A%20%20B%20--%3E%20C%0A%20%20S1%5B%22%E9%AB%98%E4%BD%8D%E9%80%89%E6%8B%A9%20s1%22%5D%20--%3E%20C%0A%20%20C%20--%3E%20Y%5B%22%E8%BE%93%E5%87%BA%3A%20%E5%9B%9B%E9%80%89%E4%B8%80%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">常见误区：初学者容易把 MUX 当成带记忆的「开关」。它是纯组合块——选择线一变输出立刻跟着变，断电重来也不记得上次选了谁；要「记住」选择结果，得在后面配寄存器。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲模拟多路开关的导通电阻、不把时钟门控当成 MUX。优先级编码器、译码器下一课才分开。总线争用（多驱动）不是 MUX；MUX 只有一个输出驱动者。</p><p>后课默认：数据通路上的选择是组合 MUX，延迟按选择树计入 \\(t_{pd}\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MUX 用选择线挑一路数据；是组合块，不是锁存。</li><li>布尔上是最小项与数据相与再或。</li><li>后课 CPU 图里的选择信号都接本课这种块。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',6))])}const U=p(B,[["render",m]]);export{M as __pageData,U as default};
